-- 2026-09-29 系统更新
-- 1. 删除测试量表 111 及其关联题目、测评答案、测评记录和随访数据
-- 2. 创建心理知识库表 psy_knowledge
-- 3. 写入心理科普文章

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

START TRANSACTION;

SET @remove_scale_id = (
  SELECT scale_id FROM psy_scale
  WHERE scale_name = '111' OR scale_code = 'crss'
  LIMIT 1
);

DELETE a FROM psy_test_answer a
JOIN psy_test_record r ON a.record_id = r.record_id
WHERE r.scale_id = @remove_scale_id;

DELETE FROM psy_follow_up
WHERE record_id IN (
  SELECT record_id FROM psy_test_record WHERE scale_id = @remove_scale_id
);

DELETE FROM psy_test_record WHERE scale_id = @remove_scale_id;
DELETE FROM psy_question WHERE scale_id = @remove_scale_id;
DELETE FROM psy_scale WHERE scale_id = @remove_scale_id;

CREATE TABLE IF NOT EXISTS `psy_knowledge` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章标题',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '心理科普' COMMENT '文章分类',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文章摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章正文',
  `author` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '系统知识库' COMMENT '作者',
  `view_count` int(11) NULL DEFAULT 0 COMMENT '阅读量',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '状态(0停用 1启用)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_knowledge_category`(`category` ASC) USING BTREE,
  INDEX `idx_knowledge_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '心理知识库表' ROW_FORMAT = DYNAMIC;

DELETE FROM psy_knowledge;

INSERT INTO psy_knowledge (title, category, summary, content, author, view_count, status) VALUES
('如何识别和缓解焦虑', '情绪管理', '了解焦虑的常见表现，并学习呼吸、记录和行动拆分等实用方法。', '焦虑是人在面对压力时常见的情绪反应，通常表现为紧张、担忧、心慌、出汗、注意力难以集中或睡眠变差。适度的焦虑可以帮助我们提高警觉，但当它持续存在并影响学习、工作和生活时，就需要认真处理。\n\n首先，可以尝试识别焦虑出现的信号：身体上是否有心跳加快、胸闷、肌肉紧绷；想法上是否反复出现“我一定会失败”“事情会变糟”；行为上是否出现逃避、拖延或反复确认。把感受写下来，有助于把模糊的焦虑变成可处理的问题。\n\n出现强烈焦虑时，可以尝试四七八呼吸：吸气四秒，屏息七秒，缓慢呼气八秒，重复四到六轮。也可以使用五指呼吸法，用手指沿着手掌轮廓慢慢移动，呼气和吸气交替进行。呼吸练习不能立刻消除所有问题，但能帮助身体从高度紧张状态慢慢降下来。\n\n接下来，把担心的事情分成两类：现在能做的和暂时无法控制的。对能做的事情，只选择一个最小行动，例如整理十分钟资料、发送一条询问信息、下楼走一圈。对无法控制的事情，练习把注意力拉回当下。如果焦虑持续两周以上，或伴随明显失眠、惊恐发作、回避社交等情况，建议到心理科或精神科进一步评估。', '系统知识库', 0, 1),
('压力很大时，可以尝试这些方法', '压力调适', '从任务拆分、身体调节、休息边界和求助四个方面缓解持续压力。', '压力并不总是坏事。适度的压力可以推动我们完成任务，但长期处于高压状态会消耗注意力、睡眠和情绪调节能力。面对压力时，不要只问“我怎样才能立刻解决全部问题”，而要先问“我现在最需要恢复哪一部分功能”。\n\n第一，拆分任务。把大任务写成可以在三十分钟内完成的小步骤，并标出优先级。每天只安排三个必须完成的关键目标，其余任务放入待办清单。这样可以减少大脑同时运转太多事项带来的负担。\n\n第二，照顾身体。规律吃饭、喝水和睡觉，是压力管理中经常被忽略的基础。每天进行二十分钟左右的散步、拉伸或慢跑，可以促进情绪恢复。深呼吸、渐进式肌肉放松和短暂闭眼休息，也适合在课间或工作间隙使用。\n\n第三，设置休息边界。连续学习或工作五十到六十分钟后，安排五到十分钟真正的休息，不刷信息、不继续处理高负荷内容。休息时可以看远处、喝水、走动或做简单伸展。\n\n第四，主动求助。把任务中的一部分交给同伴协作，或向老师、家人说明当前困难，并不等于能力不足。如果压力已经导致持续失眠、情绪失控、明显躯体不适，应尽早寻求专业帮助。', '系统知识库', 0, 1),
('睡眠卫生：改善失眠的日常策略', '睡眠健康', '通过固定作息、减少刺激、调整卧床行为和记录睡眠来改善睡眠质量。', '睡眠是情绪调节、记忆巩固和身体恢复的重要基础。偶尔失眠很常见，不必因为一晚没睡好而过度担心。真正需要关注的是失眠持续的时间、白天功能受影响的程度，以及是否伴随明显的焦虑或抑郁情绪。\n\n第一，固定起床时间。无论前一晚几点入睡，尽量在同一时间起床，帮助生物钟重新稳定。白天午睡不超过三十分钟，下午三点后尽量不要补觉。\n\n第二，减少睡前刺激。睡前一到两小时减少手机、电脑和短视频使用，避免咖啡、浓茶、酒精和剧烈运动。卧室尽量保持安静、昏暗和温度适宜，床主要用于睡觉，不在床上长时间工作或刷手机。\n\n第三，调整卧床行为。上床后二十分钟仍无法入睡，可以先起床到昏暗环境中做安静的活动，例如听舒缓音乐、阅读纸质书，等困意明显后再回到床上。不要反复看时间，也不要在床上强迫自己入睡。\n\n第四，记录睡眠日记。连续记录入睡时间、醒来次数、起床时间和白天精神状态，有助于发现规律。如果失眠持续两周以上，或已经影响学习、工作和情绪，建议前往睡眠医学科或心理科评估，不要自行长期服用安眠药。', '系统知识库', 0, 1),
('情绪低落时如何照顾自己', '情绪管理', '情绪低落时先降低行动门槛，保持基本生活节律并留意持续时间和风险信号。', '每个人都会有情绪低落的时候。低落可能来自考试、人际冲突、失去重要的人或长期压力，也可能没有明显原因。情绪低落时，最困难的事情往往不是“想开一点”，而是连起床、吃饭和回复消息都变得费力。\n\n这时可以把目标缩小到最基本的自我照顾：按时吃一顿饭，喝一杯水，洗个澡，出门走十分钟，或者给一个信任的人发一条消息。不要用“我今天什么都没做成”来评价自己，完成一个小行动本身就是恢复的一部分。\n\n让身体重新获得一点节律也很重要。尽量保持固定起床时间，白天接触自然光，进行轻度运动。情绪很低落时，不必强迫自己参加热闹的社交，但可以和一个安全的人待在一起，或进行不需要太多交流的陪伴活动。\n\n如果低落持续两周以上，伴随兴趣减退、食欲和睡眠明显变化、注意力下降、无价值感，建议寻求心理咨询或精神科评估。如果出现自伤、轻生想法，或已经制定计划，请立即联系家人、老师或专业人员，不要独处。全国心理援助热线 12356 可以提供即时支持，紧急情况下拨打 120 或 110。', '系统知识库', 0, 1),
('考试焦虑的应对方法', '压力调适', '通过考前准备、临场放松和认知调整降低考试焦虑对发挥的影响。', '考试焦虑通常表现为考前反复担心、临场心跳加快、手心出汗、大脑空白，甚至出现失眠、恶心和逃避考试。焦虑并不代表能力不足，它往往说明这件事对你很重要。关键不是彻底消除紧张，而是让紧张保持在可以发挥的水平。\n\n考前准备方面，把复习任务拆成小单元，使用模拟练习检验掌握程度，而不是反复阅读已经熟悉的内容。提前确认考试时间、地点和所需物品，减少不确定因素。考前一天避免熬夜，也不要临时大量摄入咖啡因。\n\n临场出现紧张时，可以先放下笔，双脚踩稳地面，缓慢呼吸三次，然后从周围找出五个能看到的东西、四个能触摸到的东西、三个能听到的声音、两个能闻到的气味和一个能尝到的味道。这个练习能帮助注意力从灾难化想法回到当下。\n\n当脑中反复出现“我肯定会考砸”时，可以把它改成更具体的表达：“我现在很紧张，但我会先完成第一题。”把注意力放在下一道题，而不是整场考试的结果。如果考试焦虑反复导致失眠、呕吐或无法进入考场，建议寻求心理老师或心理科帮助。', '系统知识库', 0, 1);
INSERT INTO psy_knowledge (title, category, summary, content, author, view_count, status) VALUES
('如何与家人或朋友表达自己的感受', '人际交往', '用具体事实、感受和需要代替指责，让沟通更容易被听见。', '当我们感到委屈、愤怒或失望时，很容易说出“你从来都不理解我”“都是你的错”这样的表达。对方听到指责后，往往会先进入防御状态，真正的需要反而不容易被看见。\n\n可以尝试使用“事实—感受—需要—请求”的方式沟通。例如，不说“你总是不回我消息”，而说“这两天我发了三次消息，一直没有收到回复，我有些担心，也有点失落。我希望你忙的时候可以简单告诉我一声，让我知道你没有出事。”\n\n沟通前，先确认自己现在的情绪强度和沟通目的。如果情绪过于激烈，可以暂时离开现场，等身体稍微平静后再谈。沟通中一次只讨论一个问题，避免把过去的矛盾全部翻出来。对方如果没有立刻理解，也不代表你的感受不重要。\n\n如果沟通涉及长期贬低、威胁、暴力或控制，不要只依靠沟通技巧解决，应优先保护安全，并向信任的成年人、老师、专业机构或警方求助。人际关系中的边界不是冷漠，而是让彼此都能被尊重。', '系统知识库', 0, 1),
('什么时候应该寻求心理专业帮助', '心理科普', '持续两周以上、影响功能或出现自伤风险时，应尽早寻求专业评估。', '寻求心理帮助并不意味着“精神有问题”。心理咨询和精神科评估可以帮助人们理解情绪、改善睡眠、处理创伤、调整人际关系，也可以在危机时提供安全保障。\n\n如果出现以下情况，建议考虑专业帮助：情绪低落或焦虑持续两周以上；睡眠、食欲、注意力明显受影响；对以前感兴趣的事情失去兴趣；反复出现强烈恐慌、强迫或创伤回忆；依靠酒精、药物或伤害自己来缓解痛苦；学习、工作和人际关系出现明显下降。\n\n如果出现自伤、轻生想法、制定计划或准备工具，应视为紧急情况。请立即联系家人、老师或可信任的人陪同，前往医院急诊或精神心理科，也可拨打全国心理援助热线 12356。紧急危险情况下拨打 120 或 110。\n\n第一次就诊可以提前整理三件事：症状从什么时候开始，最近睡眠和情绪有什么变化，最希望解决的问题是什么。医生或咨询师不会因为你的困难而否定你。如实表达感受，是获得有效帮助的第一步。', '系统知识库', 0, 1),
('心理援助热线与紧急情况处理', '危机支持', '了解出现自伤念头或情绪危机时可以立即采取的求助步骤。', '如果你现在有伤害自己或结束生命的想法，请先停下来，尽量不要独处。可以立即联系一个信任的家人、朋友、老师或同学，请对方陪在身边。\n\n把可能造成伤害的物品暂时交给他人保管，远离高处、危险工具或其他可能造成伤害的环境。你可以直接告诉对方：“我现在状态很危险，我需要你陪着我。”不需要独自解释所有原因。\n\n可以拨打全国心理援助热线 12356 寻求支持。如果已经准备实施伤害，或出现无法控制的冲动，请立即拨打 120 或 110，或前往最近的医院急诊。危机不会永远保持同样的强度，先确保安全，再处理后面的情绪和问题。\n\n如果你正在陪伴处于危机中的同学或家人，不要承诺替对方保密，不要独自承担全部责任。尽快联系老师、家长、学校心理老师或专业医疗机构，并保持陪伴。', '系统知识库', 0, 1),
('如何记录情绪与睡眠日记', '自我关怀', '用简单模板记录情绪、睡眠、事件和应对方式，发现变化规律。', '情绪和睡眠日记不是为了给自己打分，而是帮助你发现“什么情况下状态更好，什么情况下更容易恶化”。每天只需记录几分钟，不需要写得很长，也不必追求文字漂亮。\n\n可以使用以下模板：\n1. 今天的睡眠时间、入睡困难和醒来次数；\n2. 今天最主要的三种情绪，并给强度打 0 到 10 分；\n3. 发生的重要事件，例如考试、冲突、运动或独处；\n4. 当时做了什么，哪件事让你更舒服，哪件事让情绪更差；\n5. 明天准备尝试的一个小行动。\n\n记录一到两周后，回看是否有规律。例如，是否在熬夜后更容易焦虑，是否在运动或与朋友交流后睡眠更好。把发现交给心理老师或医生，也可以让专业评估更准确。\n\n如果记录本身让你反复陷入痛苦，可以缩短记录时间，或只记录睡眠和行动，不必强迫自己详细回忆创伤事件。', '系统知识库', 0, 1),
('青少年与家长沟通建议', '亲子关系', '通过选择时机、表达具体需要和设置边界，减少亲子沟通中的冲突。', '青少年和家长之间的冲突，常常不是因为没有感情，而是双方对独立、安全、成绩和未来的理解不同。沟通时，双方都可能觉得自己没有被听见。\n\n青少年可以先选择情绪相对平稳、没有外人在场的时机沟通。表达时尽量使用具体事实和需要，例如：“当你在同学面前批评我的成绩时，我感到很丢脸。我希望如果有问题，可以回家再谈。”这比“你总是让我难堪”更容易让对方理解。\n\n家长可以多问开放式问题，例如“你最近最担心的是什么”“你希望我怎样支持你”，并先听完再给建议。对手机、作息和外出等问题，可以和孩子一起确定清晰规则，而不是只依靠临时命令。\n\n如果冲突中出现辱骂、威胁、肢体暴力或长期冷暴力，应尽快向学校老师、心理老师、亲属或其他可信任的成年人求助。家庭问题不需要由孩子独自解决。', '系统知识库', 0, 1);

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
